Shadows = {
    init: async function (app, container, observable) {
        app = app || session.app;
        container = container || $(".component[name=Shadows]");
        if(!observable) { return; }
        $("[name=horizontaloffset]", container).kendoSlider({ 
            min: 0, 
            max: 20, 
            smallStep: 1, 
            largeStep: 2, 
            value: parseFloat(observable.get("shadows").split(" ")[0].replaceAll("px", "")),
            change: function(e) {
                e.preventDefault();
                var existingShadowValue = observable.get("shadows");
                var parts = existingShadowValue.split(" ");
                parts[0] = this.value() + "px";
                observable.set("shadows", parts.join(" "));
            }
        });
        $("[name=verticaloffset]", container).kendoSlider({ 
            min: 0, 
            max: 20, 
            smallStep: 1, 
            largeStep: 2, 
            value: parseFloat(observable.get("shadows").split(" ")[1].replaceAll("px", "")),
            change: function(e) {
                e.preventDefault();
                var existingShadowValue = observable.get("shadows");
                var parts = existingShadowValue.split(" ");
                parts[1] = this.value() + "px";
                observable.set("shadows", parts.join(" "));
            }
        });
        $("[name=blurradius]", container).kendoSlider({ 
            min: 0, 
            max: 20, 
            smallStep: 1, 
            largeStep: 2, 
            value: parseFloat(observable.get("shadows").split(" ")[2].replaceAll("px", "")),
            change: function(e) {
                e.preventDefault();
                var existingShadowValue = observable.get("shadows");
                var parts = existingShadowValue.split(" ");
                parts[2] = this.value() + "px";
                observable.set("shadows", parts.join(" "));
            }
        });
        $("[name=colour]", container).kendoColorPicker({
            buttons: false,
            value: observable.get("shadows").split(" ")[3],
            change: function(e) {
                e.preventDefault();
                var existingShadowValue = observable.get("shadows");
                var parts = existingShadowValue.split(" ");
                parts[3] = this.value();
                observable.set("shadows", parts.join(" "));
            }
        });
    }
}
